#sheet{padding:14mm 0 12mm;font-family:'LiberationSerif','DejaVu Serif',serif;line-height:1.5;}
#sheet > *{padding-left:46mm;padding-right:10mm;}
#sheet .inner > *{padding-left:46mm;padding-right:10mm;}
#sheet main > *{padding-left:46mm;padding-right:10mm;}
#sheet .frame > *{padding-left:46mm;padding-right:10mm;}
#sheet .card > *{padding-left:46mm;padding-right:10mm;}
#sheet > *:nth-child(-n+2){padding-left:6mm;padding-right:6mm;border-bottom:.7mm solid #111;padding-bottom:4mm;}
#sheet .inner > *:nth-child(-n+2){padding-left:6mm;padding-right:6mm;border-bottom:.7mm solid #111;padding-bottom:4mm;}
#sheet main > *:nth-child(-n+2){padding-left:6mm;padding-right:6mm;border-bottom:.7mm solid #111;padding-bottom:4mm;}
#sheet .frame > *:nth-child(-n+2){padding-left:6mm;padding-right:6mm;border-bottom:.7mm solid #111;padding-bottom:4mm;}
#sheet .card > *:nth-child(-n+2){padding-left:6mm;padding-right:6mm;border-bottom:.7mm solid #111;padding-bottom:4mm;}
#sheet > table.items{width:auto;margin-left:4mm;margin-right:4mm;border-top:.7mm solid #111;border-bottom:.7mm solid #111;}
#sheet .inner > table.items{width:auto;margin-left:4mm;margin-right:4mm;border-top:.7mm solid #111;border-bottom:.7mm solid #111;}
#sheet main > table.items{width:auto;margin-left:4mm;margin-right:4mm;border-top:.7mm solid #111;border-bottom:.7mm solid #111;}
#sheet .frame > table.items{width:auto;margin-left:4mm;margin-right:4mm;border-top:.7mm solid #111;border-bottom:.7mm solid #111;}
#sheet .card > table.items{width:auto;margin-left:4mm;margin-right:4mm;border-top:.7mm solid #111;border-bottom:.7mm solid #111;}
#sheet table.items th{background:transparent;border:0;border-bottom:.3mm solid #111;padding:1.6mm .8mm;}
#sheet .inner table.items th{background:transparent;border:0;border-bottom:.3mm solid #111;padding:1.6mm .8mm;}
#sheet main table.items th{background:transparent;border:0;border-bottom:.3mm solid #111;padding:1.6mm .8mm;}
#sheet .frame table.items th{background:transparent;border:0;border-bottom:.3mm solid #111;padding:1.6mm .8mm;}
#sheet .card table.items th{background:transparent;border:0;border-bottom:.3mm solid #111;padding:1.6mm .8mm;}
#sheet table.items td{border:0;padding:1.4mm .8mm;}
#sheet .inner table.items td{border:0;padding:1.4mm .8mm;}
#sheet main table.items td{border:0;padding:1.4mm .8mm;}
#sheet .frame table.items td{border:0;padding:1.4mm .8mm;}
#sheet .card table.items td{border:0;padding:1.4mm .8mm;}
#sheet .frame, #sheet .inner{border:0;padding:0;}
#sheet .inner .frame, #sheet .inner{border:0;padding:0;}
#sheet main .frame, #sheet .inner{border:0;padding:0;}
#sheet .frame .frame, #sheet .inner{border:0;padding:0;}
#sheet .card .frame, #sheet .inner{border:0;padding:0;}
#sheet > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .inner > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet main > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .frame > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet .card > table.items{margin-left:0;margin-right:0;padding-left:0;padding-right:0;width:100%;}
#sheet table.items{table-layout:fixed;}
#sheet .inner table.items{table-layout:fixed;}
#sheet main table.items{table-layout:fixed;}
#sheet .frame table.items{table-layout:fixed;}
#sheet .card table.items{table-layout:fixed;}
#sheet table.items th{overflow-wrap:anywhere;}
#sheet .inner table.items th{overflow-wrap:anywhere;}
#sheet main table.items th{overflow-wrap:anywhere;}
#sheet .frame table.items th{overflow-wrap:anywhere;}
#sheet .card table.items th{overflow-wrap:anywhere;}
#sheet table.items td{overflow-wrap:anywhere;}
#sheet .inner table.items td{overflow-wrap:anywhere;}
#sheet main table.items td{overflow-wrap:anywhere;}
#sheet .frame table.items td{overflow-wrap:anywhere;}
#sheet .card table.items td{overflow-wrap:anywhere;}
#sheet > .frame,#sheet .frame > .frame,#sheet > .card,#sheet .frame > .card,#sheet > .inner,#sheet .frame > .inner{margin-left:0;margin-right:0;background:transparent;color:inherit;}
